// AWS Lambda handler — Node.js 20 runtime
// Triggered by API Gateway POST /orders

import { DynamoDBClient, PutItemCommand } from '@aws-sdk/client-dynamodb';
import { randomUUID } from 'crypto';

// Initialize clients OUTSIDE the handler for warm container reuse
// (client creation is expensive — do it once per container lifetime)
const dynamo = new DynamoDBClient({ region: process.env.AWS_REGION });

export const handler = async (event) => {
  try {
    const body = JSON.parse(event.body ?? '{}');

    // Validate input
    if (!body.productId || !body.quantity) {
      return {
        statusCode: 400,
        body: JSON.stringify({ error: 'productId and quantity required' }),
      };
    }

    const orderId = randomUUID();
    const timestamp = new Date().toISOString();

    // Persist to DynamoDB — Lambda is stateless, state lives externally
    await dynamo.send(new PutItemCommand({
      TableName: process.env.ORDERS_TABLE,
      Item: {
        orderId:   { S: orderId },
        productId: { S: body.productId },
        quantity:  { N: String(body.quantity) },
        createdAt: { S: timestamp },
        userId:    { S: event.requestContext.authorizer.claims.sub },
      },
    }));

    return {
      statusCode: 201,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ orderId, createdAt: timestamp }),
    };
  } catch (err) {
    console.error('Order creation failed:', err);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Internal server error' }),
    };
  }
};
